<template><view class="growth-page" :class="{'motion-reduced':reducedMotion}"><view class="growth-hero"><text class="growth-eyebrow">TOGETHER · 一起体验</text><text class="growth-title">活动与预约</text><text class="growth-subtitle">在真实的相聚中，认识材料、练习表达。时间均为北京时间。</text></view><view class="growth-row filters"><view v-for="f in filters" :key="f.id" :class="['growth-tag',{active:filter===f.id}]" @click="filter=f.id">{{f.text}}</view></view><view v-if="error" class="growth-error">{{error}}<button class="growth-button secondary" @click="load">重新加载</button></view><text v-if="loading" class="growth-muted">正在查找活动…</text><view v-else-if="!visible.length&&!error" class="growth-card growth-muted">暂时没有符合条件的活动。主办人发布后会出现在这里。</view><view v-for="p in visible" :key="p.id" class="growth-card"><view class="growth-row growth-spread"><text class="growth-tag">{{names[p.kind]}}</text><text class="growth-muted">{{p.status==='CANCELLED'?'活动已取消':status[p.myStatus]||'开放报名'}}</text></view><text class="program-title">{{p.title}}</text><text class="growth-muted block">{{format(p.start_time)}} — {{format(p.end_time)}}</text><text class="growth-muted block">地点 / 方式：{{p.location}}</text><text v-if="p.co_leader" class="growth-muted block">协同带领：{{p.co_leader}}</text><text class="growth-muted block description">{{p.description}}</text><text v-if="p.materials" class="growth-muted block">准备材料：{{p.materials}}</text><text class="growth-muted block">{{p.booked}} / {{p.capacity}} 人</text><button v-if="p.myStatus==='BOOKED'" class="growth-button secondary" :disabled="!!busy" @click="act(p,true)">取消预约</button><button v-else-if="p.myStatus!=='CHECKED_IN'&&p.status==='PUBLISHED'" class="growth-button" :disabled="!!busy||p.booked>=p.capacity||ended(p)" @click="act(p,false)">{{ended(p)?'报名已结束':p.booked>=p.capacity?'名额已满':'预约参加'}}</button></view><text class="growth-foot">本系统不能替代专业心理咨询</text></view></template>
<script setup>
import {useInteraction} from '../../composables/useInteraction'
const {reducedMotion}=useInteraction()

import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import {request} from '../../utils/request'
const rows=ref([]),loading=ref(false),busy=ref(''),error=ref(''),filter=ref('ALL');const names={WORKSHOP:'主题工作坊',COURSE:'系列课程',GUIDANCE:'一对一指导'},status={BOOKED:'已预约',CHECKED_IN:'已签到',CANCELLED:'已取消预约'};const filters=[{id:'ALL',text:'全部'},{id:'WORKSHOP',text:'工作坊'},{id:'COURSE',text:'课程'},{id:'GUIDANCE',text:'一对一'},{id:'MINE',text:'我的预约'}];const visible=computed(()=>rows.value.filter(p=>filter.value==='ALL'||(filter.value==='MINE'?['BOOKED','CHECKED_IN'].includes(p.myStatus):p.kind===filter.value)))
function format(s){return s.replace('T',' ').slice(0,16)}function ended(p){return new Date(p.start_time+'+08:00').getTime()<=Date.now()}
async function load(){loading.value=true;error.value='';try{rows.value=await request({url:'/api/growth/programs'})}catch(e){error.value=e.message}finally{loading.value=false}}
function act(p,cancel){uni.showModal({title:cancel?'取消预约':'确认预约',content:cancel?'取消后名额将释放。':'请确认时间与地点。预约将保存参加记录，开始前可取消。',success:async r=>{if(!r.confirm||busy.value)return;busy.value=p.id;try{await request({url:'/api/growth/programs/'+p.id+'/book',method:cancel?'DELETE':'POST'});await load();uni.showToast({title:cancel?'已取消':'预约成功',icon:'success'})}catch(e){error.value=e.message}finally{busy.value=''}}})}onShow(load)
</script><style src="../../styles/growth.css"></style><style scoped>.filters{margin:0 0 28rpx}.active{background:#2f7566;color:#fff}.program-title{display:block;font-size:34rpx;font-weight:600;margin:24rpx 0}.block{display:block;margin:10rpx 0}.description{padding:20rpx 0;border-top:1rpx solid var(--zy-border,#e2e9e9)}</style>
